import {validateContactRows,pipeRows} from './import-validation.js';
import {workbook} from './xlsx.js';
import {Repository,getConfig,saveConfig,configured,resetLocal,assignmentStatus,occurrences} from './api.js';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',contacts:'M4 3h13a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H4z M2 7h4 M2 12h4 M2 17h4 M12 7a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M8 17a4 4 0 0 1 8 0',tasks:'M9 5H5v16h14V5h-4 M9 3h6v4H9z M8 12l2 2 5-4 M8 18h7',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2 M8 14h2 M14 14h2 M8 18h2',chart:'M3 3v18h18 M7 15v-4 M12 15V7 M17 15v-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',logout:'M9 3H3v18h6 M9 12h12 M16 7l5 5-5 5',check:'M5 12l4 4L19 6',upload:'M12 16V3 M7 8l5-5 5 5 M3 16v5h18v-5',download:'M12 3v13 M7 11l5 5 5-5 M3 17v4h18v-4',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',text:'M4 5h16 M4 10h16 M4 15h10 M4 20h7',close:'M6 6l12 12 M18 6L6 18',edit:'M16 3l5 5-12 12-6 1 1-6z M14 5l5 5',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',cloud:'M7 18a5 5 0 1 1 1-10 7 7 0 0 1 13 4 4 4 0 0 1-2 7 M12 12v9 M9 15l3-3 3 3',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',repeat:'M17 2l4 4-4 4 M3 11V8a2 2 0 0 1 2-2h16 M7 22l-4-4 4-4 M21 13v3a2 2 0 0 1-2 2H3',menu:'M3 6h18 M3 12h18 M3 18h18',phone:'M22 16.9v3a2 2 0 0 1-2.2 2A19.8 19.8 0 0 1 3.1 5.2 2 2 0 0 1 5.1 3h3l2 5-2 2a16 16 0 0 0 6 6l2-2z',info:'M12 11v6 M12 7v.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const brand=()=>'<span class="workspace-logo" role="img" aria-label="Montme"></span>';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=n=>String(n||'?').split(' ').map(v=>v[0]).slice(0,2).join('').toUpperCase();
const TZ='Asia/Kolkata', date=(v,options={})=>v?new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',...options,timeZone:TZ}).format(new Date(v)):'—';
const time=v=>date(v,{hour:'2-digit',minute:'2-digit'});
const dateKey=v=>new Intl.DateTimeFormat('en-CA',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v));
const inputDate=v=>v?new Date(new Date(v).getTime()+330*60000).toISOString().slice(0,16):'';
const fromInput=v=>v?new Date(v+':00+05:30').toISOString():null;
const sizes=v=>v<1024?`${v||0} B`:v<1048576?`${(v/1024).toFixed(1)} KB`:`${(v/1048576).toFixed(1)} MB`;
const btn=(label,action,ic='plus',cls='primary',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${icon(ic)}${label}</button>`;
const empty=(ic,title,sub,action='',label='',compact=false)=>`<div class="empty ${compact?'compact':''}"><span class="empty-icon">${icon(ic)}</span><h3>${title}</h3><p>${sub}</p>${action?btn(label,action,'plus','soft'):''}</div>`;
const badge=s=>`<span class="badge ${['Scheduled','Interested','High'].includes(s)?'orange':['Completed','Won','Active','Published'].includes(s)?'green':['Overdue','Urgent','Not interested'].includes(s)?'red':s==='Follow-up'?'blue':''}">${esc(s)}</span>`;
let repo,view='overview',search='',tab='All',employeeFilter='',calendarMonth=new Date(),assignmentMode='list',calendarScheduledOnly=false,pollTimer,rendering=false;let busy=false;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const labels={overview:'Overview',employees:'Employees',contacts:'Contacts',assignments:'Assignments',content:'Content library',reports:'Reports',settings:'Settings',roles:'Roles',activity:'Activity',dailyReports:'Daily Work Reports',notifications:'Notifications'};
const navIcons={overview:'grid',employees:'team',contacts:'contacts',assignments:'tasks',content:'file',reports:'chart',settings:'settings',roles:'shield',activity:'clock',dailyReports:'file',notifications:'bell'};
const toast=(message,tone='info')=>{
 const el=document.querySelector('#toast');
 const close=document.createElement('button');
 close.type='button';close.className='workspace-toast-dismiss';close.textContent='Dismiss';
 close.onclick=()=>el.classList.remove('show');
 el.dataset.tone=tone;el.replaceChildren(document.createTextNode(message),close);
 el.classList.add('show');clearTimeout(toast.timer);
 toast.timer=setTimeout(()=>el.classList.remove('show'),tone==='error'?8500:5000);
};
function errIn(form,error){const el=form.querySelector('.form-error');if(el){el.textContent=error.message||error;el.classList.add('show');}else toast(error.message||String(error));}
function showModal(title,subtitle,body,footer='',id=''){modal.innerHTML=`<form id="${id||'generic-form'}"><header class="modal-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button type="button" class="iconbtn" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${body}<div class="form-error" role="alert"></div></div>${footer?`<footer class="modal-foot">${footer}</footer>`:''}</form>`;if(!modal.open)modal.showModal();}
const cancel=`<button type="button" class="btn" data-action="close">Cancel</button>`;
const submit=label=>`<button type="submit" class="btn primary">${icon('check')}${label}</button>`;
function field(name,label,value='',type='text',extra=''){return `<div class="form-field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function selectField(name,label,options,value='',extra=''){return `<div class="form-field"><label for="${name}">${label}</label><select id="${name}" name="${name}" ${extra}>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`}).join('')}</select></div>`;}
const getEmployee=id=>repo.data.employees.find(e=>e.id===id);
const recipients=a=>(a.recipient_ids||[]).map(id=>getEmployee(id)?.name||'Former employee').join(', ');
const status=a=>assignmentStatus(a,repo.data.receipts);
const filtered=(rows,fn)=>rows.filter(r=>fn(r).toLowerCase().includes(search.toLowerCase()));
function renderLogin(){
 clearInterval(pollTimer);
 repo=null;
 app.innerHTML=`<main class="workspace-signin">
  <aside class="signin-brand">${brand()}</aside>
  <section class="signin-content"><div class="signin-form">
   <h1>Admin sign in</h1>
   <p>Use your workspace credentials to manage employees and assignments.</p>
   <form id="login-form">
    ${field('username','Username or email','','text','required autocomplete="username"')}
    ${field('password','Password','','password','required autocomplete="current-password"')}
    <div class="form-error" role="alert"></div>
    <button class="btn primary" ${!configured()?'disabled':''}>Sign in ${icon('arrow')}</button>
   </form>
   ${configured()?'':`<p class="signin-setup">Set up your workspace connection to sign in.
     <button class="text-link" data-action="configure">Connection settings</button></p>`}
  </div></section>
 </main>`;
}
async function start(local=false){repo=new Repository(local);if(!local)await repo.identify();await repo.load();view=canView('overview')?'overview':'assignments';search='';tab='All';render();clearInterval(pollTimer);if(!local)pollTimer=setInterval(async()=>{if(!repo||busy||document.hidden)return;const current=repo;try{await current.load();if(current!==repo)return;if(!canView(view))view='assignments';if(!modal.open&&document.activeElement?.tagName!=='INPUT'&&document.activeElement?.tagName!=='SELECT')render();}catch(e){if(current!==repo)return;if(!current.session){renderLogin();return;}current.lastError=e.message;updateConnection();}},30000);}
function updateConnection(){const el=document.querySelector('#connection');if(el)el.innerHTML=`<span class="dot ${!repo.local&&!repo.lastError?'live':''}"></span>${repo.local?'Local preview':repo.lastError?'Connection interrupted':'Connected'}`;}
function render(){if(!repo||rendering)return;rendering=true;const admin=repo.role==='admin';const names=Object.keys(labels).filter(canView);app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="workspace-label">${admin?'ADMIN WORKSPACE':'EMPLOYEE WORKSPACE'}</div><nav class="nav">${names.map(n=>`<button data-view="${n}" class="${n===view?'active':''}">${icon(navIcons[n])}${labels[n]}${n==='assignments'&&repo.data.assignments.filter(a=>status(a)==='Overdue').length?`<span class="nav-count">${repo.data.assignments.filter(a=>status(a)==='Overdue').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon(repo.local?'cloud':'shield')}<strong>${repo.local?'Your preview, on this device':'A little clarity goes a long way.'}</strong>${repo.local?'Changes stay in this browser. Connect Supabase to share work with your team.':'Give every task an owner and a next step. The rest follows.'}</div><div class="profile"><span class="avatar">${repo.owner?'L':initials(repo.employee?.name)}</span><div><strong>${repo.owner?'Lokesh':esc(repo.employee?.name)}</strong><small>${repo.owner?'Workspace owner':esc(repo.data.roles.find(r=>r.id===repo.employee?.role_id)?.name||'Employee')}</small></div><button data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><button class="iconbtn mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="breadcrumb">Workspace ${icon('chevron')} <strong>${labels[view]}</strong></div><div class="topbar-right"><div class="search">${icon('search')}<input aria-label="Search workspace" id="global-search" placeholder="Search this page…" value="${esc(search)}"><span class="key">/</span></div><button class="iconbtn" data-action="refresh" aria-label="Reload and check database">${icon('repeat')}</button><span class="connection" id="connection"></span><button class="iconbtn" data-view="notifications" aria-label="Notifications" style="position:relative">${icon('bell')}${unreadCount()?`<span class="nav-count" style="position:absolute;top:-6px;right:-7px">${unreadCount()}</span>`:''}</button><button class="iconbtn" data-view="assignments" data-mode="calendar" data-filter="Scheduled" aria-label="View scheduled work">${icon('calendar')}</button><span class="avatar">${repo.owner?'L':initials(repo.employee?.name)}</span></div></header><div class="content">${repo.local?`<div class="notice">${icon('info')}<span><strong>Local preview.</strong> Changes are saved in this browser, not delivered to employees.</span><button data-action="connect" style="margin-left:auto">Connect workspace</button></div>`:repo.lastError?`<div class="notice">${icon('info')}<span>Last refresh failed: ${esc(repo.lastError)}. Showing previously loaded data.</span>${btn('Retry','refresh','repeat','plain')}</div>`:''}<div id="view-content">${page()}</div><footer class="footer"><span>© ${new Date().getFullYear()} Montme · Every conversation counts.</span><span>All schedule times in IST (UTC +05:30)</span></footer></div></main></div>`;rendering=false;updateConnection();}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function stats(items){return `<div class="stats">${items.map(([label,val,ic,sub,dest,filter,mode])=>{const linked=dest&&canView(dest),tag=linked?'button':'article';return `<${tag} class="stat${linked?' stat-link':''}" ${linked?`type="button" data-view="${dest}" data-filter="${filter||'All'}" data-mode="${mode||'list'}"`:''}><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${val}</div><div class="stat-foot">${sub}</div></${tag}>`;}).join('')}</div>`;}
function page(){return ({overview,employees:employeesPage,contacts:contactsPage,assignments:assignmentsPage,content:contentPage,reports:reportsPage,settings:settingsPage,roles:rolesPage,activity:activityPage,dailyReports:dailyReportsPage,notifications:notificationsPage}[view]||overview)();}
function overview(){const d=repo.data,active=d.employees.filter(e=>e.active).length,scheduled=d.assignments.filter(a=>status(a)==='Scheduled'),published=d.assignments.filter(a=>['Published','Overdue'].includes(status(a)));return heading('A clear view of your team.',`Here’s what’s happening in your workspace today, ${date(new Date(),{weekday:'long'})}.`,btn('New assignment','new-assignment'))+`<section class="hero"><div class="hero-copy"><div class="eyebrow">A LITTLE DIRECTION. A LOT OF MOMENTUM.</div><h2>Keep good work moving.</h2><p>A message, a brief, a next step. Send your team what they need, right when they need it.</p>${btn('Create an assignment','new-assignment','arrow','')}</div><div class="hero-art" aria-hidden="true"><div class="bars"><span></span><span></span><span></span></div><div class="art-tag">${icon('check')} Every task. A clear next step.</div></div></section>`+stats([['Active employees',active,'team',`${d.employees.length} in your directory`,'employees','Active'],['Open assignments',published.length,'tasks',`${d.assignments.filter(a=>status(a)==='Overdue').length} overdue · ready for a follow-up`,'assignments','Open'],['Scheduled work',scheduled.length,'calendar',scheduled.length?`Next: ${time(scheduled.sort((a,b)=>new Date(a.release_at)-new Date(b.release_at))[0].release_at)}`:'Plan your next team update','assignments','Scheduled','calendar'],['Business contacts',d.contacts.length,'contacts',`${d.contacts.filter(c=>c.status==='New').length} new leads in the pipeline`,'contacts']])+`<div class="grid-main"><div><section class="panel"><header class="panel-head"><div><h2>Recent assignments</h2><p>The latest direction shared with your team.</p></div><button class="text-link" data-view="assignments">View all ${icon('arrow')}</button></header>${d.assignments.length?assignmentTable(d.assignments.slice(0,5),true):empty('tasks','Every good task starts here','Create your first assignment with a message, a file or a link.','new-assignment','Create assignment')}</section><section class="panel"><header class="panel-head"><div><h2>Your people</h2><p>A quick look at your team.</p></div><button class="text-link" data-view="employees">Manage team ${icon('arrow')}</button></header>${d.employees.length?employeeTable(d.employees.slice(0,4),true):empty('team','Bring your team together','Add employees to assign contacts, share content and plan work.','new-employee','Add employee',true)}</section></div><div><section class="panel"><header class="panel-head"><div><h2>Coming up next</h2><p>Right message. Right time.</p></div>${icon('calendar')}</header>${scheduled.length?scheduled.slice(0,4).map(scheduleRow).join(''):empty('calendar','A little room to plan','Scheduled assignments will appear here, ready for their moment.','','',true)}<div style="padding:0 20px 18px">${btn('Open calendar','go-schedule','calendar','')}</div></section><section class="panel"><header class="panel-head"><h2>Make this workspace yours</h2><span class="badge orange">Quick start</span></header><div class="panel-body"><ol class="setup-list">${[['1','Add your people','Create an employee directory and invite your team.','employees'],['2','Build your content library','Keep PDFs, links and messages ready to share.','content'],['3','Give the next step an owner','Assign work now, or schedule it for later.','assignments']].map(([n,t,s,v])=>`<li><span class="step">${n}</span><div><button class="text-link" data-view="${v}" style="text-align:left"><strong>${t}</strong></button><p>${s}</p></div></li>`).join('')}</ol></div></section></div></div>`;}
function person(e){return `<div class="person"><span class="avatar">${initials(e.name)}</span><div><strong>${esc(e.name)}</strong><div class="secondary">${esc(e.email||e.institution||e.company||'')}</div></div></div>`;}
function employeeTable(rows,compact=false){return `<div class="table-wrap"><table><thead><tr><th>Employee</th><th>Employee ID</th><th>Access role</th><th>Status</th>${compact?'':'<th>Assignments</th><th>Actions</th>'}</tr></thead><tbody>${rows.map(e=>`<tr><td>${person(e)}</td><td>${esc(e.employee_code)}</td><td>${esc(repo.data.roles.find(r=>r.id===e.role_id)?.name||'Employee')}</td><td>${badge(e.active?'Active':'Inactive')}</td>${compact?'':`<td>${repo.data.assignments.filter(a=>a.recipient_ids?.includes(e.id)).length}</td><td><div class="row-actions">${btn('Edit','edit-employee','edit','plain',`data-id="${e.id}"`)}${btn('Assign work','employee-work','tasks','plain',`data-id="${e.id}"`)}</div></td>`}</tr>`).join('')}</tbody></table></div>`;}
function employeesPage(){const rows=filtered(repo.data.employees,e=>`${e.name} ${e.email} ${e.employee_code}`).filter(e=>tab==='All'||(tab==='Active'===e.active));return heading('Good work starts with your people.','Manage access, assign work and keep your team connected.',btn('Add employee','new-employee','plus'))+`<section class="panel">${toolbar(['All','Active','Inactive'],'Search name, email or employee ID')} ${rows.length?employeeTable(rows):empty('team',repo.data.employees.length?'No employees match your search':'Your team belongs here','Create an employee profile to start sharing work.','new-employee','Add employee')}</section>`+
 `<section class="panel"><header class="panel-head"><h2>Employee clock-out schedules</h2></header>
 <div class="panel-body"><p>Times repeat daily in India Standard Time. Employees without a schedule can clock out after two hours.</p>
 ${!repo.local&&!repo.attendanceAvailable?'<p>Schedule editing requires the company backend upgrade.</p>':rows.map(e=>`<div class="setting-row"><div><strong>${esc(e.name)}</strong><p>${e.clock_out_time?esc(e.clock_out_time.slice(0,5))+' IST':'Two hours after clock-in'}</p></div>
 ${btn('Set clock-out time','set-clock-out','clock','',`data-id="${esc(e.id)}"`)}</div>`).join('')}</div></section>`;}
function toolbar(tabs,placeholder,extra=''){return `<div class="toolbar"><div class="tabs">${tabs.map(t=>`<button data-tab="${t}" class="${tab===t?'active':''}">${t}</button>`).join('')}</div><div class="actions">${extra}<div class="search">${icon('search')}<input id="page-search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(search)}"></div></div></div>`;}
function contactsPage(){const rows=filtered(repo.data.contacts,c=>`${c.name} ${c.institution||c.company} ${c.phone} ${c.email}`).filter(c=>(tab==='All'||c.status===tab)&&(!employeeFilter||c.assigned_employee_id===employeeFilter));const options=`<select id="employee-filter" aria-label="Filter by employee"><option value="">All employees</option>${repo.data.employees.map(e=>`<option value="${e.id}" ${employeeFilter===e.id?'selected':''}>${esc(e.name)} (${esc(e.employee_code)})</option>`).join('')}</select>`;return heading('Better conversations start here.','Keep contacts organised, assigned and ready for the next call.',btn('Import contacts','import-contacts','upload','')+btn('Add contact','new-contact'))+`<section class="panel">${toolbar(['All','New','Contacted','Interested','Follow-up','Won'],'Search contacts',options)}${rows.length?`<div class="table-wrap"><table><thead><tr><th>Contact</th><th>Institution</th><th>Phone</th><th>Assigned to</th><th>Status</th><th>Follow-up</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td>${person(c)}</td><td>${esc(c.institution||c.company||'')}</td><td>${esc(c.phone)}</td><td>${esc(getEmployee(c.assigned_employee_id)?.name||'Unassigned')}</td><td>${badge(c.status)}</td><td>${c.follow_up_at?time(c.follow_up_at):'—'}</td><td><button class="iconbtn" aria-label="Edit ${esc(c.name)}" data-action="edit-contact" data-id="${c.id}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('contacts',repo.data.contacts.length?'No matching contacts':'A fresh pipeline','Add contacts individually or paste a list to import.','new-contact','Add contact')}</section>`;}
function assignmentTable(rows,compact=false){const employee=repo.role==='employee';return `<div class="table-wrap"><table><thead><tr><th>Assignment</th>${employee?'':'<th>Assigned to</th>'}<th>Status</th>${compact?'':'<th>Delivery / due</th><th>Progress</th>'}<th></th></tr></thead><tbody>${rows.map(a=>{const done=repo.data.receipts.filter(r=>r.assignment_id===a.id&&r.status==='completed').length;const read=repo.data.receipts.filter(r=>r.assignment_id===a.id).length;return `<tr><td><button class="text-link" data-action="view-assignment" data-id="${a.id}" style="text-align:left;color:var(--ink)">${esc(a.title)}</button><div class="secondary">${icon(a.repeat_rule!=='none'?'repeat':a.content_ids?.length?'file':'text')} ${esc(a.priority)} priority${a.content_ids?.length?` · ${a.content_ids.length} attachment${a.content_ids.length===1?'':'s'}`:''}</div></td>${employee?'':`<td><span title="${esc(recipients(a))}">${a.recipient_ids?.length===1?esc(recipients(a)):`${a.recipient_ids?.length||0} employees`}</span></td>`}<td>${badge(status(a))}</td>${compact?'':`<td>${time(a.release_at)}<div class="secondary">Due ${a.due_at?time(a.due_at):'not set'}</div></td><td>${done}/${a.recipient_ids.length} completed<div class="secondary">${read} read</div></td>`}<td><button class="iconbtn" data-action="view-assignment" data-id="${a.id}" aria-label="Open assignment">${icon('chevron')}</button></td></tr>`}).join('')}</tbody></table></div>`;}
function assignmentViews(){return `<div class="tabs assignment-views" aria-label="Assignment view">
 <button type="button" data-action="assignment-list" aria-pressed="${assignmentMode==='list'}">List</button>
 <button type="button" data-action="assignment-calendar" aria-pressed="${assignmentMode==='calendar'}">Calendar</button>
 </div>`;}
function assignmentsPage(){if(assignmentMode==='calendar')return schedulePage();const admin=repo.role==='admin';const rows=filtered(repo.data.assignments,a=>`${a.title} ${a.message} ${recipients(a)}`).filter(a=>tab==='All'||(tab==='Open'?['Published','Overdue'].includes(status(a)):status(a)===tab));return heading(admin?'A clear next step. For everyone.':'Your next steps, in one place.',admin?'Send messages, share files and assign work with a date and an owner.':'Read your assignments, download attachments and mark work complete.',admin?btn('New assignment','new-assignment'):'')+assignmentViews()+`<section class="panel">${toolbar(admin?['All','Open','Published','Scheduled','Overdue','Completed','Draft']:['All','Open','Published','Overdue','Completed'],'Search assignments')}${rows.length?assignmentTable(rows):empty('tasks',repo.data.assignments.length?'No assignments match':'No assignments yet',admin?'Give your team a task, a brief, or a little direction.':'Your admin’s published assignments will appear here.',admin?'new-assignment':'',admin?'Create assignment':'')}</section>`;}
function contentPage(){const admin=repo.role==='admin';const rows=filtered(repo.data.content,c=>`${c.title} ${c.body} ${c.file_name||''}`).filter(c=>tab==='All'||c.kind===tab.toLowerCase());return heading('The right resources. Ready to share.','A home for your files, links and reusable messages.',admin?btn('New message','new-text','text','')+btn('Add link','new-link','link','')+btn('Upload files','upload','upload'):'')+`<section class="panel">${toolbar(['All','File','Text','Link'],'Search your library')}</section>${rows.length?`<div class="file-grid">${rows.map(c=>`<article class="file-card"><div class="file-card-top"><span class="file-icon">${icon(c.kind==='file'?'file':c.kind==='link'?'link':'text')}</span>${badge(c.kind==='file'?(c.file_name?.split('.').pop()?.toUpperCase()||'FILE'):c.kind==='text'?'Message':'Link')}</div><div><h3 title="${esc(c.title)}">${esc(c.title)}</h3><p>${esc(c.kind==='file'?sizes(c.size_bytes):c.body.slice(0,110))}</p></div><div class="file-card-foot"><span>${date(c.created_at)}</span><div class="row-actions"><button class="text-link" data-action="view-content" data-id="${c.id}">${c.kind==='file'?'Download':'Open'} ${icon(c.kind==='file'?'download':'arrow')}</button>${admin?`<button class="btn plain" data-action="delete-content" data-id="${c.id}" aria-label="Delete ${esc(c.title)}">${icon('trash')}</button>`:''}</div></div></article>`).join('')}</div>`:`<section class="panel">${empty('file','Make room for useful things','Upload a PDF, save a link, or write a message to assign to your team.',admin?'upload':'',admin?'Upload your first file':'')}</section>`}`;}
function scheduleRow(a){const d=new Date(a.release_at);return `<button class="schedule-row" style="width:100%;text-align:left" data-action="view-assignment" data-id="${a.id}"><span class="schedule-date"><strong>${date(d,{day:'2-digit'}).split(' ')[0]}</strong><small>${date(d,{month:'short'}).split(' ').pop()}</small></span><span class="schedule-details"><h3>${esc(a.title)}</h3><p>${date(d,{hour:'2-digit',minute:'2-digit'}).split(',').pop()} · ${a.recipient_ids.length} recipient${a.recipient_ids.length===1?'':'s'}</p></span>${badge(status(a))}</button>`;}
function calendarMonthFor(value=new Date()){
 const [year,month]=dateKey(value).split('-').map(Number);
 return new Date(year,month-1,1);
}
function calendarItems(){return repo.data.assignments.filter(a=>
 a.state!=='cancelled'&&a.state!=='draft'&&(!calendarScheduledOnly||status(a)==='Scheduled'));}
function schedulePage(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth();const first=new Date(y,m,1),offset=(first.getDay()+6)%7;const start=new Date(y,m,1-offset);const scheduled=calendarItems();return heading('Assignments','Plan delivery dates, deadlines and repeating assignments in IST.',repo.role==='admin'?btn('Schedule assignment','schedule-assignment','calendar'):'')+assignmentViews()+
 `<div class="actions assignment-calendar-filter"><button class="btn" type="button" data-action="calendar-filter" aria-pressed="${calendarScheduledOnly}">Upcoming only</button></div><section class="panel"><header class="panel-head"><div class="calendar-title"><h2>${new Intl.DateTimeFormat('en-IN',{month:'long',year:'numeric'}).format(first)}</h2><span class="badge">IST</span></div><div class="actions">${btn('Today','calendar-today','calendar','plain')}<div class="month-controls"><button class="iconbtn" data-action="month-prev" aria-label="Previous month" style="transform:rotate(180deg)">${icon('chevron')}</button><button class="iconbtn" data-action="month-next" aria-label="Next month">${icon('chevron')}</button></div></div></header><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const items=scheduled.filter(a=>dateKey(a.release_at)===key);return `<div class="calendar-day ${d.getMonth()!==m?'outside':''}"><span class="day-number ${key===dateKey(new Date())?'today':''}">${d.getDate()}</span>${items.slice(0,3).map(a=>`<button class="cal-item" data-action="view-assignment" data-id="${a.id}" title="${esc(a.title)}">${esc(a.title)}</button>`).join('')}${items.length>3?`<button class="text-link" data-action="calendar-day" data-day="${key}" style="font-size:9px;margin-top:5px">+${items.length-3} more</button>`:''}</div>`}).join('')}</div></section><div class="notice">${icon('clock')}<span>Scheduled work becomes visible to its recipients at the delivery time. Repeating work creates separate assignments with individual completion tracking.</span></div>`;}
function reportsPage(){const d=repo.data,calls=d.calls.filter(c=>!employeeFilter||c.employee_id===employeeFilter),shifts=d.shifts.filter(s=>!employeeFilter||s.employee_id===employeeFilter),connected=calls.filter(c=>c.duration_seconds>0).length;const total=calls.reduce((s,c)=>s+c.duration_seconds,0);const days=[...new Set(calls.map(c=>dateKey(c.started_at)))].sort().slice(-7);const max=Math.max(1,...days.map(d=>calls.filter(c=>dateKey(c.started_at)===d).length));return heading('See the work behind the numbers.','Reports use synced records only. Missing data stays empty.',btn('Export call report','export-calls','download',''))+`<div class="actions" style="margin-bottom:20px"><label class="filter-label" for="employee-filter">Employee</label><select id="employee-filter" style="padding:9px;border:1px solid var(--border);border-radius:7px"><option value="">All employees</option>${d.employees.map(e=>`<option value="${e.id}" ${employeeFilter===e.id?'selected':''}>${esc(e.name)} (${esc(e.employee_code)})</option>`).join('')}</select><span class="muted small">All synced dates · up to 5,000 records per table</span></div>`+stats([['Business calls',calls.length,'phone','Synced from employee devices'],['Connected calls',connected,'check',`${calls.length?Math.round(connected/calls.length*100):0}% connection rate`],['Talk time',`${Math.floor(total/60)} min`,'clock','Actual imported conversation time'],['Shift records',shifts.length,'calendar',`${shifts.filter(s=>!s.ended_at).length} currently open`]])+`<div class="grid-main"><section class="panel"><header class="panel-head"><div><h2>Call activity</h2><p>Last seven recorded days.</p></div></header>${days.length?`<div class="panel-body"><div class="analytics-bars">${days.map(day=>`<div class="analytics-bar"><strong>${calls.filter(c=>dateKey(c.started_at)===day).length}</strong><span style="height:${calls.filter(c=>dateKey(c.started_at)===day).length/max*120}px"></span><label>${date(day+'T12:00:00+05:30')}</label></div>`).join('')}</div></div>`:empty('chart','No synced calls yet','Employee device syncing must be connected before call reports appear. No placeholder data is shown.','','',true)}</section><section class="panel"><header class="panel-head"><h2>Assignment outcomes</h2></header><div class="panel-body">${['Published','Scheduled','Completed','Overdue'].map(s=>{const num=d.assignments.filter(a=>status(a)===s).length;return `<div style="margin-bottom:18px"><div style="display:flex;justify-content:space-between;font-size:11px"><span>${s}</span><strong>${num}</strong></div><div class="progress-track"><span style="width:${num/Math.max(1,d.assignments.length)*100}%"></span></div></div>`}).join('')}</div></section></div><section class="panel"><header class="panel-head"><h2>Recent calls</h2></header>${calls.length?`<div class="table-wrap"><table><thead><tr><th>Employee</th><th>Phone</th><th>Time</th><th>Duration</th><th>Outcome</th><th>Source</th></tr></thead><tbody>${calls.slice(0,100).map(c=>`<tr><td>${esc(getEmployee(c.employee_id)?.name||'Employee')}</td><td>${esc(c.phone)}</td><td>${time(c.started_at)}</td><td>${Math.floor(c.duration_seconds/60)}m ${c.duration_seconds%60}s</td><td>${esc(c.outcome)}</td><td>${badge(c.source)}</td></tr>`).join('')}</tbody></table></div>`:empty('phone','Your next conversation will show here','Existing local app records have not been uploaded. Connect employee accounts to begin syncing.','','',true)}</section>`;}
function settingsPage(){return heading('A workspace that works for you.','Manage your connection, account and workspace data.')+`<div class="setting-grid"><section class="panel"><header class="panel-head"><h2>Connection</h2>${badge(repo.local?'Local preview':'Supabase')}</header><div class="panel-body"><div class="setting-row"><div><strong>Project</strong><p>${esc(getConfig().url||'Not configured')}</p></div>${icon('cloud')}</div><div class="setting-row"><div><strong>Last successful refresh</strong><p>${repo.lastSync?time(repo.lastSync):'No server refresh in local preview'}</p></div></div><div class="setting-row"><div><strong>Refresh interval</strong><p>Every 30 seconds while this workspace is active.</p></div></div><div class="actions" style="margin-top:16px">${btn('Connection settings','configure','settings','')}${repo.local?btn('Sign in to Supabase','connect','arrow','primary'):btn('Refresh now','refresh','repeat','')}</div></div></section><section class="panel"><header class="panel-head"><h2>Your account</h2></header><div class="panel-body"><div class="setting-row"><div><strong>Signed in as</strong><p>${repo.role==='admin'?'lokesh · Administrator':esc(repo.employee?.name)}</p></div><span class="avatar">${repo.owner?'L':initials(repo.employee?.name)}</span></div><div class="setting-row"><div><strong>Workspace timezone</strong><p>India Standard Time · Asia/Kolkata</p></div><span class="badge">UTC +05:30</span></div><div class="setting-row"><div><strong>Files</strong><p>Private storage · 20 MB per file · signed download links</p></div></div><div style="margin-top:16px">${repo.local?'':btn('Change password','password','shield','')}</div></div></section>${repo.role==='admin'?`<section class="panel"><header class="panel-head"><h2>Employee access</h2></header><div class="panel-body"><p class="muted small">Create employees with their ID, email, password and access role. Set an initial password when adding them. Employees sign in using their employee ID and that password. Only enrolled, active employees can access assignments.</p><div class="actions" style="margin-top:16px">${btn('Add employee','new-employee','team','')}${btn('Copy workspace link','copy-link','link','')}</div></div></section><section class="panel"><header class="panel-head"><h2>Workspace data</h2></header><div class="panel-body"><p class="muted small">${repo.local?'Preview data belongs to this browser. Clearing it does not affect Supabase.':'Export the currently loaded workspace data for your records. Uploaded files are not included in this JSON export.'}</p><div class="actions" style="margin-top:16px">${btn('Export workspace','export-workspace','download','')}${repo.local?btn('Clear local preview','clear-local','trash','danger'):''}</div></div></section>`:''}</div>`;}
function employeeForm(id){
 const e=repo.data.employees.find(x=>x.id===id)||{},roles=repo.data.roles;
 showModal(e.id?'Edit employee':'Bring someone on board.','Create a managed account with an employee ID, password and access role.',`<div class="form-grid">${field('name','Full name',e.name,'text','required maxlength="100"')}${field('employee_code','Employee ID',e.employee_code,'text','required minlength="2" maxlength="40" pattern="[A-Za-z0-9][A-Za-z0-9._-]{1,39}"')}${field('email','Work email',e.email,'email','required')}${field('phone','Phone number',e.phone,'tel','maxlength="30"')}${field('role','Job title',e.role||'Employee','text','maxlength="80"')}${selectField('role_id','Access role',roles.filter(r=>repo.can('roles.manage')||!r.permissions?.length||r.id===e.role_id).map(r=>[r.id,r.name]),e.role_id||roles.find(r=>r.name==='Employee')?.id||'')}${selectField('active','Access status',[['true','Active'],['false','Inactive']],String(e.active??true))}${field('password',e.auth_id?'Reset password (leave blank to keep current)':'Initial password','','password',`${e.auth_id?'':'required'} minlength="8" maxlength="128" autocomplete="new-password"`)}</div><div class="notice" style="margin-top:20px;margin-bottom:0">${icon('shield')}<span>${repo.local?'Local preview saves directory details only. Passwords are discarded and no real login account or email is created.':'Employee signs in using the Employee ID and this password. Share credentials privately. Passwords are handled by Supabase Auth and are never saved in the employee table.'}</span></div>`,cancel+submit(e.id?'Save employee':'Create employee account'),'employee-form');modal.querySelector('form').dataset.id=e.id||'';
}
function contactForm(id){const c=repo.data.contacts.find(x=>x.id===id)||{};showModal(c.id?'Edit contact':'A new conversation starts here.','Keep the right details close to hand.',`<div class="form-grid">${field('name','Contact name',c.name,'text','required maxlength="150"')}${field('institution','Institution',c.institution||c.company,'text','required maxlength="150"')}${field('phone','Phone number',c.phone,'tel','required maxlength="25" placeholder="+91 98765 43210"')}${field('email','Email (optional)',c.email,'email')}${selectField('assigned_employee_id','Assign employee',[['','Unassigned'],...repo.data.employees.filter(e=>e.active).map(e=>[e.id,e.name])],c.assigned_employee_id||'')}${selectField('status','Lead status',['New','Contacted','Interested','Follow-up','Won','Not interested'],c.status||'New')}${field('follow_up_at','Follow-up date & time (IST)',inputDate(c.follow_up_at),'datetime-local')}<div class="form-field field-full"><label for="notes">Notes</label><textarea id="notes" name="notes" maxlength="10000">${esc(c.notes)}</textarea></div></div>`,(c.id?`<button type="button" class="btn plain danger left" data-action="delete-contact" data-id="${c.id}">${icon('trash')}Delete contact</button>`:'')+cancel+submit('Save contact'),'contact-form');modal.querySelector('form').dataset.id=c.id||'';}
function assignmentForm(id='',preset='',schedule=false){const a=repo.data.assignments.find(x=>x.id===id)||{};const people=repo.data.employees.filter(e=>e.active||a.recipient_ids?.includes(e.id));const now=new Date(Date.now()+3600000);const content=repo.data.content;showModal(a.id?'Edit assignment':'Give good work a clear next step.','Messages, resources and deadlines — all in one assignment.',`<div class="form-grid"><div class="field-full">${field('title','Assignment title',a.title,'text','required maxlength="180" placeholder="e.g. Follow up with this week’s new leads"')}</div><div class="form-field field-full"><label for="message">Message / instructions</label><textarea id="message" name="message" maxlength="20000" placeholder="Tell your team what needs to happen. Add instructions or paste links here.">${esc(a.message)}</textarea></div><div class="form-field field-full"><div style="display:flex;justify-content:space-between"><label>Assign to</label><button type="button" class="text-link" data-action="select-recipients">Select all active</button></div>${people.length?`<div class="recipient-list">${people.map(e=>`<label class="check"><input type="checkbox" name="recipient_ids" value="${e.id}" ${a.recipient_ids?.includes(e.id)||e.id===preset?'checked':''} ${!e.active?'disabled':''}><span>${esc(e.name)}<small>${esc(e.employee_code)}${!e.active?' · Inactive':''}</small></span></label>`).join('')}</div>`:`<div class="notice" style="margin:0">Add at least one active employee before creating an assignment.</div>`}</div>${selectField('priority','Priority',['Normal','High','Urgent'],a.priority||'Normal')}${selectField('delivery','Delivery',[['now','Send now'],['schedule','Schedule for later'],['draft','Save as draft']],a.state==='draft'?'draft':a.release_at&&new Date(a.release_at)>new Date()||schedule?'schedule':'now')}<div id="release-wrap">${field('release_at','Delivery date & time (IST)',inputDate(a.release_at||now),'datetime-local')}</div>${field('due_at','Due date & time (IST, optional)',inputDate(a.due_at),'datetime-local')}${a.id?`<div class="field-full small muted">Editing this occurrence only. ${a.series_id?'Other occurrences in this series remain unchanged.':''}</div>`:`${selectField('repeat_rule','Repeat',['none','daily','weekly','monthly'].map(v=>[v,v==='none'?'Does not repeat':v[0].toUpperCase()+v.slice(1)]),'none')}<div id="repeat-wrap" hidden>${field('repeat_until','Repeat through (IST)','','date')}</div>`}<div class="form-field field-full"><label>Attach content from your library</label>${content.length?`<div class="recipient-list" style="grid-template-columns:1fr">${content.map(c=>`<label class="check"><input type="checkbox" name="content_ids" value="${c.id}" ${a.content_ids?.includes(c.id)?'checked':''}>${icon(c.kind==='text'?'text':c.kind==='link'?'link':'file')}<span>${esc(c.title)}<small>${c.kind==='file'?sizes(c.size_bytes):c.kind==='text'?'Message':'Link'}</small></span></label>`).join('')}</div>`:`<div class="drop-zone" style="padding:15px">No content yet. Upload files or save messages in Content library before attaching them.</div>`}<small>PDF, TXT and other files can be uploaded in Content library. Text and links can also be pasted directly into the message.</small></div></div>`,cancel+submit(a.id?'Save changes':'Create assignment'),'assignment-form');const f=modal.querySelector('form');f.dataset.id=a.id||'';updateAssignmentFields();}
function updateAssignmentFields(){const f=modal.querySelector('#assignment-form');if(!f)return;const scheduled=f.delivery.value==='schedule';f.querySelector('#release-wrap').hidden=!scheduled;f.release_at.required=scheduled;const r=f.querySelector('#repeat-wrap');if(r){r.hidden=f.repeat_rule.value==='none';f.repeat_until.required=f.repeat_rule.value!=='none';}const b=f.querySelector('button[type="submit"]');b.innerHTML=icon(f.delivery.value==='schedule'?'calendar':f.delivery.value==='draft'?'file':'arrow')+(f.dataset.id?'Save changes':f.delivery.value==='draft'?'Save draft':f.delivery.value==='schedule'?'Schedule assignment':'Send assignment');}
function textForm(kind,id=''){const c=repo.data.content.find(x=>x.id===id)||{};showModal(kind==='link'?'A useful link, ready to share.':'A message worth keeping.',kind==='link'?'Save a resource to attach to future assignments.':'Write once. Share it whenever your team needs it.',field('title','Title',c.title,'text','required maxlength="180"')+(kind==='link'?field('body','Link URL',c.body,'url','required placeholder="https://…"'):`<div class="form-field"><label for="body">Message</label><textarea id="body" name="body" required maxlength="20000" style="min-height:180px">${esc(c.body)}</textarea></div>`),cancel+submit('Save to library'),'content-form');const f=modal.querySelector('form');f.dataset.kind=kind;f.dataset.id=c.id||'';}
function uploadForm(){showModal('A little knowledge goes a long way.','Upload resources and assign them to the people who need them.',`<label class="drop-zone" style="display:block">${icon('upload')}<strong>Choose files</strong> or drop them here<small>PDF, TXT, documents, images and more · Up to 20 MB per file</small><input type="file" id="files" name="files" multiple required aria-label="Choose files to upload"></label><div id="selected-files" class="small muted" style="margin-top:15px"></div><div class="notice" style="margin-top:20px;margin-bottom:0">${icon('shield')}<span>${repo.local?'Files stay in this browser’s local storage in preview mode.':'Uploads stay private. Only admins and recipients of published assignments can download them.'}</span></div>`,cancel+submit('Upload files'),'upload-form');}
async function viewContent(id){const c=repo.data.content.find(x=>x.id===id);if(!c)return;if(c.kind==='file'){await downloadItem(c);return;}showModal(c.title,c.kind==='text'?'Saved message':'Saved link',c.kind==='text'?`<div class="detail-text">${linkify(c.body)}</div>`:`<p class="prewrap">${linkify(c.body)}</p>`,`<button type="button" class="btn" data-action="close">Close</button>${repo.role==='admin'?btn('Edit','edit-content','edit','primary',`data-id="${c.id}"`):''}`);}
function linkify(text){
 const raw=String(text||'');let cursor=0,out='';
 for(const m of raw.matchAll(/https?:\/\/[^\s<>"']+/g)){out+=esc(raw.slice(cursor,m.index));try{const url=new URL(m[0]);out+=`<a href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">${esc(m[0])}</a>`;}catch{out+=esc(m[0]);}cursor=m.index+m[0].length;}
 return out+esc(raw.slice(cursor));
}
async function downloadItem(c){const url=await repo.fileUrl(c);const a=document.createElement('a');a.href=url;a.download=c.file_name||c.title;a.target='_blank';a.rel='noopener';document.body.append(a);a.click();a.remove();if(repo.local)setTimeout(()=>URL.revokeObjectURL(url),60000);}
function viewAssignment(id){const a=repo.data.assignments.find(x=>x.id===id);if(!a)return;const admin=repo.role==='admin';const receipts=repo.data.receipts.filter(r=>r.assignment_id===id);showModal(a.title,`${a.priority} priority · ${status(a)}`,`<div class="detail-text">${a.message?linkify(a.message):'<span class="muted">No additional message.</span>'}</div><div class="detail-meta"><div>Delivery<strong>${time(a.release_at)} IST</strong></div><div>Due<strong>${a.due_at?time(a.due_at)+' IST':'No deadline'}</strong></div><div>Repeat<strong>${a.repeat_rule||'none'}</strong></div></div><h3 style="margin:22px 0 10px">Resources</h3>${a.content_ids?.length?a.content_ids.map(id=>{const c=repo.data.content.find(x=>x.id===id);return c?`<div class="attachment"><span class="file-icon">${icon(c.kind==='text'?'text':c.kind==='link'?'link':'file')}</span><div><strong>${esc(c.title)}</strong><small>${c.kind==='file'?sizes(c.size_bytes):c.kind==='text'?'Message':'Link'}</small></div><button type="button" class="text-link" data-action="view-content" data-id="${c.id}">${c.kind==='file'?'Download':'Open'} ${icon('arrow')}</button></div>`:''}).join(''):'<p class="muted small">No resources attached.</p>'}<h3 style="margin:23px 0 10px">${admin?'Recipients & progress':'Your progress'}</h3>${(admin?a.recipient_ids:[repo.employee.id]).map(id=>{const e=getEmployee(id),r=receipts.find(r=>r.employee_id===id);return `<div class="attachment"><span class="avatar">${initials(e?.name)}</span><strong>${esc(e?.name||'Employee')}</strong><span class="status-check">${r?.status==='completed'?badge('Completed'):r?badge('Read'):badge('Not read')}</span></div>`}).join('')}`,(admin?`${a.state!=='cancelled'?btn('Edit','edit-assignment','edit','',`data-id="${id}"`)+btn('Cancel assignment','cancel-assignment','close','danger',`data-id="${id}"`):''}${a.series_id?btn('Cancel future repeats','cancel-series','repeat','danger',`data-id="${a.series_id}"`):''}`:btn('Mark complete','complete-assignment','check','primary',`data-id="${id}"`))+`<button type="button" class="btn" data-action="close">Close</button>`);if(!admin&&!receipts.some(r=>r.employee_id===repo.employee.id)){repo.receipt(id,'read').then(()=>repo.load()).catch(e=>toast(e.message));}}
function configForm(){const c=getConfig();showModal('Connect your Montme workspace.','Use the public project URL and publishable key from Supabase.',field('url','Supabase Project URL',c.url,'url','required')+field('key','Publishable / anon key',c.key,'text','required autocomplete="off"')+field('adminEmail','Admin email (username: lokesh)',c.adminEmail,'email','required')+`<div class="notice" style="margin:0">${icon('shield')}<span>Use only the public publishable or anon key. Never paste a database password, secret key or service-role key here.</span></div>`,cancel+submit('Save connection'),'config-form');}
function registerForm(){showModal('Join your team.','Your admin must add your email to the employee directory first.',field('email','Invited work email','','email','required autocomplete="email"')+field('password','Choose a password','','password','required minlength="8" autocomplete="new-password"')+field('confirm','Confirm password','','password','required minlength="8" autocomplete="new-password"'),cancel+submit('Create employee account'),'register-form');}
let contactImport=null;
function importContacts(){contactImport=null;showModal('Bring your contacts along.','Upload Excel or a text-based PDF. Review validation before saving.',`<div class="form-field"><label for="contact-file">Excel (.xlsx) or PDF</label><input type="file" id="contact-file" accept=".xlsx,.pdf" aria-label="Upload contacts file"><small>Required columns: Contact name, Phone, Institution. Email is optional. One contact per row; up to 500 contacts, 20 MB.</small></div><div class="actions" style="margin-bottom:16px">${btn('Download Excel template','contact-template','download','')}<span class="small muted">Phone numbers should be formatted as Text.</span></div><details><summary class="small muted" style="cursor:pointer">Or paste a table using | separators</summary><div class="form-field" style="margin-top:12px"><label for="bulk">Include the header row</label><textarea name="bulk" id="bulk" rows="5" placeholder="Contact name | Phone | Institution | Email&#10;Asha Rao | +919876543210 | Example Institute | asha@example.com"></textarea></div><button type="button" class="btn" data-action="validate-pasted">Validate pasted rows</button></details><div id="import-result" style="margin-top:18px" aria-live="polite"></div>`,cancel+`<button type="submit" id="save-contact-import" class="btn primary" disabled>${icon('check')}Import validated contacts</button>`,'import-form');}
function showImportResult(result){contactImport=result;const errors=result.errors||[];document.querySelector('#save-contact-import').disabled=errors.length>0||!result.contacts?.length;document.querySelector('#import-result').innerHTML=errors.length?`<div class="import-errors"><strong>Upload with the full required content.</strong><ul>${errors.slice(0,30).map(e=>`<li>${esc(e)}</li>`).join('')}</ul>${errors.length>30?`<p>And ${errors.length-30} more errors.</p>`:''}<p>No contacts have been imported.</p></div>`:`<div class="notice">${icon('check')}<span>${result.contacts.length} valid contacts. ${result.duplicates} existing or duplicate numbers skipped. Review below before importing.</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Phone</th><th>Institution</th></tr></thead><tbody>${result.contacts.slice(0,8).map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.phone)}</td><td>${esc(c.institution)}</td></tr>`).join('')}</tbody></table></div>${result.contacts.length>8?`<p class="muted small">Showing 8 of ${result.contacts.length} contacts.</p>`:''}`;}
async function saveForm(form,fn){
 if(busy)return;
 busy=true;
 const buttons=[...form.querySelectorAll('button')];
 const submitButton=form.querySelector('button[type=submit]');
 const original=submitButton?.innerHTML;
 form.querySelector('.form-error')?.classList.remove('show');
 form.setAttribute('aria-busy','true');
 if(submitButton){submitButton.classList.add('is-pending');submitButton.textContent='Saving…';}
 buttons.forEach(button=>button.disabled=true);
 try{
  await fn();
  modal.close();
  try{if(repo)await repo.load();if(repo)render();}
  catch{toast('Changes saved. Refresh to load the latest records.','info');}
 }catch(error){
  errIn(form,error);
 }finally{
  busy=false;
  form.removeAttribute('aria-busy');
  buttons.forEach(button=>button.disabled=false);
  if(submitButton){submitButton.classList.remove('is-pending');submitButton.innerHTML=original;}
 }
}
async function confirmAction(title,description,fn){showModal(title,'',`<p class="small muted">${esc(description)}</p>`,cancel+submit('Confirm'),'confirm-form');modal.querySelector('form').confirmFn=fn;}
function download(name,data,mime='application/json'){const url=URL.createObjectURL(new Blob([data],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
app.addEventListener('submit',async event=>{if(event.target.id!=='login-form')return;event.preventDefault();const form=event.target,b=form.querySelector('button');b.disabled=true;b.classList.add('is-pending');form.setAttribute('aria-busy','true');form.querySelector('.form-error').classList.remove('show');b.textContent='Signing in…';try{const r=new Repository();await r.login(form.username.value,form.password.value);await start(false);}catch(e){errIn(form,e);}finally{b.disabled=false;b.classList.remove('is-pending');form.removeAttribute('aria-busy');b.innerHTML='Sign in '+icon('arrow');}});
modal.addEventListener('submit',event=>{event.preventDefault();const f=event.target,fd=new FormData(f);const val=n=>String(fd.get(n)||'').trim();const id=f.dataset.id;
 if(f.id==='employee-form')saveForm(f,async()=>{const email=val('email').toLowerCase(),code=val('employee_code');if(repo.data.employees.some(e=>e.id!==id&&(e.email.toLowerCase()===email||e.employee_code.toLowerCase()===code.toLowerCase())))throw Error('This email or employee ID already exists.');const savedEmployee=await repo.saveEmployee({...(id?{id}:{}),name:val('name'),email,employee_code:code,phone:val('phone'),role:val('role')||'Employee',role_id:val('role_id'),active:val('active')==='true',password:String(fd.get('password')||'')});toast(savedEmployee?.welcome_email?.status==='sent'?'Employee saved. Welcome email accepted by Gmail.':savedEmployee?.welcome_email?'Employee saved. Welcome email '+savedEmployee.welcome_email.status+': '+savedEmployee.welcome_email.message:'Employee saved.');});
 else if(f.id==='contact-form')saveForm(f,async()=>{const phone=val('phone'),digits=phone.replace(/\D/g,'');if(!/^\+?[\d\s()-]+$/.test(phone)||digits.length<7||digits.length>15)throw Error('Enter a valid phone number.');if(repo.data.contacts.some(c=>c.id!==id&&c.phone.replace(/\D/g,'')===digits))throw Error('This phone number is already in your contacts.');await repo.save('contacts',{...(id?{id}:{}),name:val('name'),phone,institution:val('institution'),email:val('email'),assigned_employee_id:val('assigned_employee_id')||null,status:val('status'),notes:val('notes'),follow_up_at:fromInput(val('follow_up_at'))});toast('Contact saved.');});
 else if(f.id==='content-form')saveForm(f,async()=>{if(f.dataset.kind==='link'&&!/^https?:\/\//i.test(val('body')))throw Error('Use a link starting with https:// or http://.');await repo.save('content',{...(id?{id}:{}),title:val('title'),body:val('body'),kind:f.dataset.kind});toast('Saved to your content library.');});
 else if(f.id==='upload-form')saveForm(f,async()=>{const files=[...f.files.files];if(files.length>20)throw Error('Upload up to 20 files at a time.');if(files.some(x=>x.size>20*1024*1024||!x.size))throw Error('Every file must be nonempty and smaller than 20 MB.');let count=0;for(const file of files){try{await repo.upload(file);count++;f.querySelector('button[type="submit"]').textContent=`Uploading ${count} / ${files.length}…`;}catch(e){throw Error(`${count} file(s) uploaded. ${file.name}: ${e.message}`);}}toast(`${count} file(s) uploaded.`);});
 else if(f.id==='assignment-form')saveForm(f,async()=>{const recipient_ids=fd.getAll('recipient_ids'),content_ids=fd.getAll('content_ids');if(!recipient_ids.length)throw Error('Select at least one active employee.');if(!val('title'))throw Error('Enter an assignment title.');const delivery=val('delivery'),release=delivery==='schedule'?fromInput(val('release_at')):new Date().toISOString(),due=fromInput(val('due_at'));if(delivery==='schedule'&&new Date(release)<new Date(Date.now()-60000))throw Error('Choose a future delivery date.');if(due&&new Date(due)<new Date(release))throw Error('The deadline must be after delivery.');const repeat=val('repeat_rule')||'none';if(delivery==='draft'&&repeat!=='none')throw Error('Save repeating work as a scheduled assignment, or choose Does not repeat.');const a={title:val('title'),message:val('message'),recipient_ids,content_ids,priority:val('priority'),state:delivery==='draft'?'draft':'published',release_at:release,due_at:due,repeat_rule:repeat};if(id){const old=repo.data.assignments.find(a=>a.id===id);await repo.save('assignments',{...a,id,repeat_rule:old.repeat_rule,series_id:old.series_id});}else{const dates=occurrences(release,val('repeat_until')?val('repeat_until')+'T23:59:59+05:30':null,repeat),series_id=repeat==='none'?null:crypto.randomUUID(),duration=due?new Date(due)-new Date(release):null;await repo.saveAssignments(dates.map(d=>({...a,series_id,release_at:d.toISOString(),due_at:duration===null?null:new Date(+d+duration).toISOString()})));}toast(delivery==='draft'?'Draft saved.':delivery==='schedule'?'Assignment scheduled.':repo.local?'Assignment saved in local preview.':'Assignment published to your team.');});
 else if(f.id==='config-form')saveForm(f,async()=>{saveConfig({url:val('url'),key:val('key'),adminEmail:val('adminEmail')});if(repo){await repo.logout();repo=null;}renderLogin();toast('Connection saved. Sign in to your workspace.');});
 else if(f.id==='password-form')saveForm(f,async()=>{if(val('password')!==val('confirm'))throw Error('Passwords do not match.');await repo.request('/auth/v1/user',{method:'PUT',body:{password:val('password')}});toast('Password updated.');});
 else if(f.id==='import-form')saveForm(f,async()=>{if(!contactImport||contactImport.errors.length||!contactImport.contacts.length)throw Error('Upload and validate a complete contact file first.');const rows=contactImport.contacts;if(repo.local){for(const r of rows)await repo.save('contacts',r);}else await repo.request('/rest/v1/contacts',{method:'POST',body:rows});toast(`${rows.length} contacts imported.`);});
 else if(f.id==='confirm-form')saveForm(f,async()=>{await f.confirmFn();toast('Done.');});
});
async function handleClick(event){const target=event.target.closest('[data-action],[data-view],[data-tab]');if(!target)return;const {action,id}=target.dataset;if(target.dataset.view){if(!canView(target.dataset.view)){toast('Your role does not allow this page.');return;}view=target.dataset.view;search='';tab=target.dataset.filter||'All';employeeFilter='';
if(view==='assignments'){
 assignmentMode=target.dataset.mode||'list';
 calendarScheduledOnly=tab==='Scheduled'&&assignmentMode==='calendar';
 if(calendarScheduledOnly){
  const next=calendarItems().slice().sort((a,b)=>Date.parse(a.release_at)-Date.parse(b.release_at))[0];
  calendarMonth=calendarMonthFor(next?.release_at);
  tab='All';
 }
}
render();return;}if(target.dataset.tab){tab=target.dataset.tab;render();return;}try{const permission=actionPermission(action);if(permission&&!repo.can(permission)){throw Error('Your role does not allow this action.');}switch(action){case'close':if(!busy)modal.close();break;case'configure':configForm();break;case'connect':if(repo)await repo.logout();renderLogin();break;case'logout':await repo.logout();renderLogin();break;case'menu':document.querySelector('.shell').classList.toggle('menu-open');break;case'refresh':
 target.disabled=true;target.classList.add('is-pending');
 try{await repo.load();render();toast('Workspace refreshed.','success');}
 finally{target.disabled=false;target.classList.remove('is-pending');}
 break;case'new-employee':employeeForm();break;case'edit-employee':employeeForm(id);break;case'new-contact':contactForm();break;case'edit-contact':contactForm(id);break;case'import-contacts':importContacts();break;case'new-assignment':assignmentForm();break;case'edit-assignment':assignmentForm(id);break;case'employee-work':assignmentForm('',id);break;case'schedule-assignment':assignmentForm('','',true);break;case'select-recipients':{const inputs=[...modal.querySelectorAll('[name="recipient_ids"]:not(:disabled)')];const check=inputs.some(i=>!i.checked);inputs.forEach(i=>i.checked=check);break;}case'view-assignment':viewAssignment(id);break;case'new-text':textForm('text');break;case'new-link':textForm('link');break;case'edit-content':{const c=repo.data.content.find(x=>x.id===id);textForm(c.kind,id);break;}case'upload':uploadForm();break;case'view-content':await viewContent(id);break;case'delete-content':{const c=repo.data.content.find(x=>x.id===id);await confirmAction('Remove this resource?',`“${c.title}” will be removed. Resources used by assignments cannot be deleted.`,()=>repo.deleteContent(c));break;}case'delete-contact':await confirmAction('Delete this contact?','This contact will be removed. Existing call history remains.',()=>repo.remove('contacts',id));break;case'cancel-assignment':await confirmAction('Cancel this assignment?','The assignment will become unavailable to employees. Existing completion records remain.',()=>repo.save('assignments',{id,state:'cancelled'}));break;case'cancel-series':await confirmAction('Cancel future repeats?','All future occurrences in this series will be cancelled. Already delivered assignments remain.',()=>repo.cancelSeries(id));break;case'complete-assignment':await repo.receipt(id,'completed');await repo.load();modal.close();render();toast('Assignment marked complete.');break;case'go-schedule':view='assignments';tab='All';search='';assignmentMode='calendar';calendarScheduledOnly=false;render();break;
case'assignment-list':assignmentMode='list';render();break;
case'assignment-calendar':assignmentMode='calendar';calendarScheduledOnly=false;render();break;
case'calendar-filter':calendarScheduledOnly=!calendarScheduledOnly;render();break;case'month-prev':calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1);render();break;case'month-next':calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1);render();break;case'calendar-today':calendarMonth=calendarMonthFor();render();break;case'calendar-day':{const items=calendarItems().filter(a=>dateKey(a.release_at)===target.dataset.day);showModal('Scheduled work',date(target.dataset.day+'T12:00:00+05:30'),items.map(scheduleRow).join(''),'<button type="button" class="btn" data-action="close">Close</button>');break;}case'copy-link':await navigator.clipboard.writeText(location.origin+location.pathname);toast('Workspace link copied.');break;case'export-workspace':download(`montme-workspace-${dateKey(new Date())}.json`,JSON.stringify(repo.data,null,2));toast('Workspace data exported. Files are not included.');break;case'export-calls':{const rows=[['Employee','Phone','Call date/time (IST)','Duration seconds','Direction','Outcome','Source','Notes'],...repo.data.calls.filter(c=>!employeeFilter||c.employee_id===employeeFilter).map(c=>[getEmployee(c.employee_id)?.name||'',c.phone,time(c.started_at),c.duration_seconds,c.direction,c.outcome,c.source,c.notes])];download('montme-admin-calls.xlsx',workbook(rows),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');break;}case'clear-local':await confirmAction('Clear this browser’s preview?','This clears local preview records and files. Supabase data is unaffected.',resetLocal);break;case'register':registerForm();break;case'password':showModal('Update your password.','Choose a password for your Supabase account.',field('password','New password','','password','required minlength="8" autocomplete="new-password"')+field('confirm','Confirm new password','','password','required minlength="8" autocomplete="new-password"'),cancel+submit('Update password'),'password-form');break;}}catch(e){toast(e.message||String(e),'error');}}
app.addEventListener('click',handleClick);modal.addEventListener('click',handleClick);modal.addEventListener('cancel',e=>{if(busy)e.preventDefault()});
modal.addEventListener('change',e=>{if(e.target.id==='delivery'||e.target.id==='repeat_rule')updateAssignmentFields();if(e.target.id==='files'){document.querySelector('#selected-files').textContent=[...e.target.files].map(f=>`${f.name} (${sizes(f.size)})`).join(' · ');}});
app.addEventListener('input',event=>{if(!['global-search','page-search'].includes(event.target.id))return;search=event.target.value;const focused=event.target.id,pos=event.target.selectionStart;document.querySelector('#view-content').innerHTML=page();const input=document.querySelector('#'+focused);if(input){input.value=search;if(focused==='page-search'){input.focus();input.setSelectionRange(pos,pos);}}if(focused==='global-search'){const p=document.querySelector('#page-search');if(p)p.value=search;}});
app.addEventListener('change',e=>{if(e.target.id==='employee-filter'){employeeFilter=e.target.value;render();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!modal.open){e.preventDefault();document.querySelector('#global-search')?.focus();}});
const permissionLabels={'employees.manage':'Manage employees and passwords','roles.manage':'Create and assign access roles','contacts.manage':'Manage and import contacts','assignments.manage':'Manage assignments and content','activity.view':'View team activity and attendance','notifications.manage':'Send notifications and view receipts','settings.manage':'Manage break and push settings','attendance.approve':'Approve early clock-out','reports.read':'View and download employee reports'};
let activityDay='',activityKind='';
function canView(name){if(!repo)return false;if(name==='activity')return repo.can('activity.view')||repo.can('attendance.approve');const required={employees:'employees.manage',roles:'roles.manage',contacts:'contacts.manage',activity:'activity.view',dailyReports:'reports.read',reports:'activity.view'};if(required[name])return repo.can(required[name]);if(name==='overview')return repo.role==='admin';if(['assignments','content'].includes(name))return repo.role==='employee'||repo.can('assignments.manage')||repo.can('activity.view');return ['notifications','settings'].includes(name);}
function actionPermission(action){const rules={'new-employee':'employees.manage','edit-employee':'employees.manage','employee-work':'assignments.manage','new-contact':'contacts.manage','edit-contact':'contacts.manage','delete-contact':'contacts.manage','import-contacts':'contacts.manage','new-assignment':'assignments.manage','schedule-assignment':'assignments.manage','edit-assignment':'assignments.manage','cancel-assignment':'assignments.manage','cancel-series':'assignments.manage','new-text':'assignments.manage','new-link':'assignments.manage','edit-content':'assignments.manage','upload':'assignments.manage','delete-content':'assignments.manage','export-calls':'activity.view'};return rules[action];}
function inboxRows(){return repo.data.notifications.filter(n=>!n.cancelled_at&&new Date(n.available_at)<=new Date()&&(n.audience==='admin'?repo.canReceiveAdminNotice(n):n.employee_id===repo.employee?.id));}
function notificationReceipt(n){return repo.data.notificationReceipts.find(r=>r.notification_id===n.id&&r.user_id===(repo.local?'preview-admin':repo.session.user.id));}
function unreadCount(){return inboxRows().filter(n=>!notificationReceipt(n)?.read_at).length;}
function rolesPage(){return heading('Give every role the right access.','Create clear responsibilities. Permissions are enforced by the server.',btn('Create role','new-role','shield'))+`<div class="notice">${icon('shield')}<span>The workspace owner keeps full access. Job titles do not grant permissions. The default Employee role has access to assigned work only.</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Role</th><th>Permissions</th><th>Employees</th><th></th></tr></thead><tbody>${repo.data.roles.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td style="white-space:normal;max-width:420px">${r.permissions.length?r.permissions.map(p=>`<span class="badge" style="margin:2px">${esc(permissionLabels[p]||p)}</span>`).join(''):'Assigned work and own activity only'}</td><td>${repo.data.employees.filter(e=>e.role_id===r.id).length}</td><td>${r.name==='Employee'?'<span class="muted small">Default role</span>':btn('Edit','edit-role','edit','plain',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function roleForm(id){const r=repo.data.roles.find(r=>r.id===id)||{};showModal(r.id?'Edit access role':'Create an access role','Only select the management permissions this role needs.',field('name','Role name',r.name,'text','required maxlength="80"')+`<div class="recipient-list" style="grid-template-columns:1fr;max-height:350px">${Object.entries(permissionLabels).map(([key,label])=>`<label class="check"><input type="checkbox" name="permissions" value="${key}" ${r.permissions?.includes(key)?'checked':''}>${label}</label>`).join('')}</div>`,(r.id?`<button type="button" class="btn danger left" data-action="delete-role" data-id="${r.id}">${icon('trash')}Delete role</button>`:'')+cancel+submit('Save role'),'role-form');modal.querySelector('form').dataset.id=r.id||'';}
function durationLabel(seconds){const value=Math.max(0,Math.floor(seconds));return `${Math.floor(value/3600)}h ${Math.floor(value%3600/60)}m ${value%60}s`;}
function shiftBreakSeconds(s){const until=new Date(s.ended_at||new Date());return (s.breaks||[]).reduce((total,b)=>total+Math.max(0,(Math.min(+new Date(b.end||new Date()),+until)-Math.max(+new Date(b.start),+new Date(s.started_at)))/1000),0);}
function activityPage(){if(!repo.can('activity.view'))return heading('Attendance approvals','Review employee requests to leave early.')+reviewRequests();const d=repo.data,shifts=d.shifts.filter(s=>(!employeeFilter||s.employee_id===employeeFilter)&&(!activityDay||dateKey(s.started_at)===activityDay)),breaks=d.breaks.filter(b=>(!employeeFilter||b.employee_id===employeeFilter)&&(!activityDay||dateKey(b.started_at)===activityDay)),events=filtered(d.activity,e=>`${e.title} ${e.kind} ${getEmployee(e.employee_id)?.name||''}`).filter(e=>(!employeeFilter||e.employee_id===employeeFilter)&&(!activityDay||dateKey(e.occurred_at)===activityDay)&&(!activityKind||e.kind===activityKind));return reviewRequests()+heading('Every shift. Every break. Recorded.','Last recorded activity from employee devices. Offline devices may have newer unsynced records.',btn('Refresh activity','refresh','repeat',''))+`<div class="actions" style="margin-bottom:20px"><select id="employee-filter" aria-label="Filter activity employee" class="activity-select"><option value="">All employees</option>${d.employees.map(e=>`<option value="${e.id}" ${employeeFilter===e.id?'selected':''}>${esc(e.name)} (${esc(e.employee_code)})</option>`).join('')}</select><input type="date" id="activity-day" value="${activityDay}" class="activity-select" aria-label="Activity date"><button class="btn plain" data-action="clear-activity-date">All dates</button></div>`+stats([['Recorded shifts',shifts.length,'clock',`${shifts.filter(s=>!s.ended_at).length} open in the latest records`],['Recorded breaks',breaks.length,'clock',`${breaks.filter(b=>!b.ended_at).length} currently open`],['Break time',durationLabel(shifts.reduce((n,s)=>n+shiftBreakSeconds(s),0)),'calendar','Calculated from recorded intervals'],['Break overruns',breaks.filter(b=>b.deadline_at&&new Date(b.ended_at||new Date())>new Date(b.deadline_at)).length,'bell','Alerts recorded for employee and admin']])+`<section class="panel"><header class="panel-head"><h2>Shift and work history</h2><span class="muted small">Gross time minus recorded breaks</span></header>${shifts.length?`<div class="table-wrap"><table><thead><tr><th>Employee</th><th>Clock in</th><th>Clock out</th><th>Break time</th><th>Net work</th></tr></thead><tbody>${shifts.slice(0,100).map(s=>`<tr><td>${esc(getEmployee(s.employee_id)?.name||'Employee')}</td><td>${time(s.started_at)}</td><td>${s.ended_at?time(s.ended_at):badge('Open')}</td><td>${durationLabel(shiftBreakSeconds(s))}</td><td>${durationLabel((new Date(s.ended_at||new Date())-new Date(s.started_at))/1000-shiftBreakSeconds(s))}</td></tr>`).join('')}</tbody></table></div>`:empty('clock','No shift data in this view','Employee clock-in and clock-out records appear after the device syncs.','','',true)}</section><section class="panel"><header class="panel-head"><h2>Break intervals</h2><span class="muted small">Lunch 1:30–2:30 · Evening 5:00–5:30 · Extra 10 min, once daily</span></header>${breaks.length?`<div class="table-wrap"><table><thead><tr><th>Employee</th><th>Break</th><th>Start</th><th>End</th><th>Duration</th><th>Allowed until</th><th>Status</th></tr></thead><tbody>${breaks.slice(0,100).map(b=>{const exceeded=b.deadline_at&&new Date(b.ended_at||new Date())>new Date(b.deadline_at);return `<tr><td>${esc(getEmployee(b.employee_id)?.name||'Employee')}</td><td>${esc(b.kind)}</td><td>${time(b.started_at)}</td><td>${b.ended_at?time(b.ended_at):'In progress'}</td><td>${durationLabel((new Date(b.ended_at||new Date())-new Date(b.started_at))/1000)}</td><td>${b.deadline_at?time(b.deadline_at):'—'}</td><td>${badge(exceeded?'Overdue':b.ended_at?'Completed':'Active')}</td></tr>`}).join('')}</tbody></table></div>`:empty('clock','No break intervals yet','Actual start, end and elapsed time are recorded when an employee takes a break.','','',true)}</section><section class="panel"><header class="panel-head"><h2>Activity timeline</h2><select id="activity-kind" class="activity-select" aria-label="Activity type"><option value="">All activity</option>${[...new Set(d.activity.map(e=>e.kind))].map(k=>`<option value="${esc(k)}" ${activityKind===k?'selected':''}>${esc(k.replaceAll('_',' '))}</option>`).join('')}</select></header>${events.length?`<div class="table-wrap"><table><thead><tr><th>Employee</th><th>Activity</th><th>Occurred at</th><th>Received by server</th></tr></thead><tbody>${events.slice(0,100).map(e=>`<tr><td>${esc(getEmployee(e.employee_id)?.name||'System')}</td><td>${esc(e.title)}</td><td>${time(e.occurred_at)}</td><td>${time(e.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('chart','No activity in this view','Timeline events appear after employee devices upload work records.','','',true)}</section>`;}
function notificationsPage(){const team=repo.can('notifications.manage')||repo.can('activity.view'),inbox=inboxRows().filter(n=>tab==='Unread'?!notificationReceipt(n)?.read_at:tab==='Read'?!!notificationReceipt(n)?.read_at:true);const teamRows=filtered(repo.data.notifications.filter(n=>n.audience==='employee'),n=>`${n.title} ${getEmployee(n.employee_id)?.name||''}`);return heading('The right update. Seen by the right person.','Keep track of alerts, employee read status and actual delivery results.',(repo.can('notifications.manage')?btn('Send notification','new-notification','bell'):'')+btn('Enable browser alerts','browser-alerts','bell',''))+`<section class="panel">${toolbar(['Inbox','Unread','Read',...(team?['Team receipts','Delivery']:[])],'Search notifications')}${tab==='Team receipts'?teamRows.length?`<div class="table-wrap"><table><thead><tr><th>Notification</th><th>Employee</th><th>Delivery time</th><th>Current status</th><th>First read</th></tr></thead><tbody>${teamRows.map(n=>{const employee=getEmployee(n.employee_id),r=repo.data.notificationReceipts.find(r=>r.notification_id===n.id&&r.user_id===employee?.auth_id);return `<tr><td>${esc(n.title)}<div class="secondary">${n.priority}</div></td><td>${esc(employee?.name||'Employee')}</td><td>${time(n.available_at)}</td><td>${badge(n.cancelled_at?'Cancelled':new Date(n.available_at)>new Date()?'Scheduled':r?.read_at?'Read':'Unread')}</td><td>${r?.first_read_at?time(r.first_read_at):'Not read'}</td></tr>`}).join('')}</tbody></table></div>`:empty('bell','No employee notifications yet','Notifications will show each employee’s current read/unread status here.','','',true):tab==='Delivery'?deliveryTable():inbox.length?`<div class="notification-list">${filtered(inbox,n=>`${n.title} ${n.body}`).map(n=>{const read=!!notificationReceipt(n)?.read_at;return `<article class="notification-item ${read?'':'unread'}"><div class="notification-symbol">${icon(n.kind.includes('break')?'clock':'bell')}</div><div class="notification-copy"><div style="display:flex;gap:10px;align-items:center"><h3>${esc(n.title)}</h3>${badge(read?'Read':'Unread')}</div><p>${esc(n.body)}</p><small>${time(n.available_at)} IST · ${esc(n.priority)} priority</small></div><button class="text-link" data-action="toggle-notification" data-id="${n.id}" data-read="${!read}">Mark ${read?'unread':'read'}</button></article>`}).join('')}</div>`:empty('bell','You’re up to date','New employee activity and work notifications will appear here.','','',true)}</section><div class="notice">${icon('info')}<span>Browser alerts work while this dashboard is open. Email and Android background push require the configured provider and scheduler. “Sent” means the provider accepted delivery; it does not mean the employee read it.</span></div>`;}
function deliveryTable(){const rows=repo.data.deliveries;return rows.length?`<div class="table-wrap"><table><thead><tr><th>Notification</th><th>Channel</th><th>Status</th><th>Attempts</th><th>Result / last error</th></tr></thead><tbody>${rows.slice(0,150).map(d=>{const n=repo.data.notifications.find(n=>n.id===d.notification_id);return `<tr><td>${esc(n?.title||'Notification')}</td><td>${esc(d.channel)}</td><td>${badge(d.status)}</td><td>${d.attempts}</td><td style="white-space:normal;max-width:350px">${esc(d.last_error|| (d.sent_at?'Accepted '+time(d.sent_at):'Queued for delivery'))}</td></tr>`}).join('')}</tbody></table></div>`:empty('cloud','No delivery attempts yet','High-priority email and push attempts appear here after the worker runs.','','',true);}
function notificationForm(){const people=repo.data.employees.filter(e=>e.active);showModal('Send a team notification','High and Urgent messages also queue email to the employee’s recorded address.',field('title','Notification title','','text','required maxlength="180"')+`<div class="form-field"><label for="body">Message</label><textarea id="body" name="body" required maxlength="10000"></textarea></div>`+selectField('priority','Priority',['Normal','High','Urgent'],'Normal')+`<div class="form-field"><label>Recipients</label><div class="recipient-list">${people.map(e=>`<label class="check"><input type="checkbox" name="recipient_ids" value="${e.id}">${esc(e.name)}</label>`).join('')}</div></div>`,cancel+submit('Send notification'),'notification-form');}
function breakSettingsForm(){const st=repo.data.settings[0]||{};showModal('Break policy and push configuration','Schedule times use IST. Provider secrets belong only in Supabase secrets.',`<div class="form-grid">${field('lunch_start','Lunch starts',String(st.lunch_start||'13:30').slice(0,5),'time','required')}${field('lunch_end','Lunch ends',String(st.lunch_end||'14:30').slice(0,5),'time','required')}${field('evening_start','Evening starts',String(st.evening_start||'17:00').slice(0,5),'time','required')}${field('evening_end','Evening ends',String(st.evening_end||'17:30').slice(0,5),'time','required')}${field('extra_break_minutes','Extra break minutes',st.extra_break_minutes||10,'number','required min="1" max="60"')}<div class="form-field"><label>Extra break frequency</label><input value="Once per IST calendar day" disabled></div><div class="field-full"><h3>Firebase public Android configuration</h3><p class="small muted" style="margin-top:6px">Optional until Firebase is created. Enter all four fields to activate device registration. Never enter a private key here.</p></div>${field('firebase_project','Project ID',st.firebase_config?.projectId)}${field('firebase_app','Android app ID',st.firebase_config?.appId)}${field('firebase_sender','Project number / sender ID',st.firebase_config?.senderId)}${field('firebase_api','Android public API key',st.firebase_config?.apiKey)}
 <div class="field-full"><h3>Employee browser notifications</h3><p class="small muted">Use a Firebase web app in the same Firebase project as the delivery service.</p></div>
 ${field('web_project','Web Firebase project ID',st.firebase_config?.web?.projectId)}
 ${field('web_app','Web Firebase app ID',st.firebase_config?.web?.appId)}
 ${field('web_sender','Web messaging sender ID',st.firebase_config?.web?.messagingSenderId)}
 ${field('web_api','Web public API key',st.firebase_config?.web?.apiKey)}
 ${field('web_vapid_key','Web Push public key',st.firebase_config?.web_vapid_key)}
 ${field('company_name','Company name',st.company_name||'Montme','text','required maxlength="120"')}<label class="check field-full"><input type="checkbox" name="email_high_priority" ${st.email_high_priority!==false?'checked':''}>Queue email for High and Urgent notifications</label></div>`,cancel+submit('Save settings'),'break-settings-form');}
const originalSettingsPage=settingsPage;
settingsPage=function(){return originalSettingsPage()+`<section class="panel"><header class="panel-head"><h2>Break rules and notification providers</h2></header><div class="panel-body"><p class="muted small">Lunch 1:30–2:30 PM, evening 5:00–5:30 PM, and one 10-minute extra break daily by default. Android local reminders work without Firebase. Background push needs Firebase; email needs Resend and a verified sender.</p><div class="actions" style="margin-top:16px">${repo.can('settings.manage')?btn('Manage rules & Firebase','break-settings','settings',''):''}${repo.can('notifications.manage')?btn('Check delivery setup','delivery-health','cloud','')+btn('Process pending alerts','dispatch-alerts','repeat','')+btn('Retry blocked deliveries','retry-alerts','repeat',''):''}</div><div id="delivery-health" class="muted small" style="margin-top:15px"></div></div></section>`;};
async function featureClick(e){const target=e.target.closest('[data-action]');if(!target)return;const {action,id}=target.dataset;try{switch(action){case'new-role':case'edit-role':if(!repo.can('roles.manage'))throw Error('Role management permission required.');roleForm(id);break;case'delete-role':if(!repo.can('roles.manage'))throw Error('Role management permission required.');if(repo.data.employees.some(e=>e.role_id===id))throw Error('Reassign employees before deleting this role.');await confirmAction('Delete this role?','Employees must be reassigned before deleting a role.',()=>repo.remove('roles',id));break;case'new-notification':if(!repo.can('notifications.manage'))throw Error('Notification permission required.');notificationForm();break;case'toggle-notification':await repo.markNotification(id,target.dataset.read==='true');await repo.load();render();break;case'browser-alerts':if(!('Notification'in window))throw Error('This browser does not support device alerts. The inbox still works.');toast(await Notification.requestPermission()==='granted'?'Browser alerts enabled.':'Browser alerts are not enabled. Your inbox remains available.');break;case'break-settings':if(!repo.can('settings.manage'))throw Error('Settings permission required.');breakSettingsForm();break;case'delivery-health':{const h=await repo.deliveryAction('health');document.querySelector('#delivery-health').textContent=`Email: ${h.email?'configured':'not configured'} · Firebase server: ${h.push?'configured':'not configured'} · Scheduled worker secret: ${h.scheduler?'configured':'not configured'}`;break;}case'dispatch-alerts':{const result=await repo.deliveryAction('dispatch');await repo.load();render();toast(`Processed alerts: ${result.sent} sent, ${result.blocked} need provider setup.`);break;}case'retry-alerts':{const count=await repo.retryDeliveries();toast(`${count} deliveries requeued. The scheduler will retry them.`);await repo.load();render();break;}case'clear-activity-date':activityDay='';render();break;case'contact-template':download('montme-contact-template.xlsx',workbook([['Contact name','Phone','Institution','Email']]),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');break;case'validate-pasted':showImportResult(validateContactRows(pipeRows(modal.querySelector('#bulk').value),repo.data.contacts));break;}}catch(error){toast(error.message||String(error));}}
app.addEventListener('click',featureClick);modal.addEventListener('click',featureClick);
app.addEventListener('change',e=>{if(e.target.id==='activity-day'){activityDay=e.target.value;render();}if(e.target.id==='activity-kind'){activityKind=e.target.value;render();}});
modal.addEventListener('change',async e=>{if(e.target.id!=='contact-file')return;const file=e.target.files[0];contactImport=null;document.querySelector('#save-contact-import').disabled=true;const el=document.querySelector('#import-result');el.textContent='Reading and validating file…';try{const {parseContactFile}=await import('./contact-import.js');const result=await parseContactFile(file,repo.data.contacts);if(modal.open&&document.querySelector('#import-form'))showImportResult(result);}catch(error){if(modal.open&&document.querySelector('#import-form'))showImportResult({contacts:[],duplicates:0,errors:[error.message]});}});
modal.addEventListener('submit',e=>{const f=e.target,fd=new FormData(f),v=n=>String(fd.get(n)||'').trim();if(f.id==='role-form'){e.preventDefault();saveForm(f,async()=>{if(!repo.can('roles.manage'))throw Error('Role management permission required.');await repo.save('roles',{...(f.dataset.id?{id:f.dataset.id}:{}),name:v('name'),permissions:fd.getAll('permissions')});toast('Role saved.');});}else if(f.id==='notification-form'){e.preventDefault();saveForm(f,async()=>{const ids=fd.getAll('recipient_ids');if(!ids.length)throw Error('Select at least one employee.');await repo.sendNotification({title:v('title'),body:v('body'),recipient_ids:ids,priority:v('priority')});toast(repo.local?'Notification saved in local preview.':'Notification queued for the selected employees.');});}else if(f.id==='break-settings-form'){e.preventDefault();saveForm(f,async()=>{if(v('lunch_end')<=v('lunch_start')||v('evening_end')<=v('evening_start'))throw Error('Each break window must end after it starts.');const firebase_config={projectId:v('firebase_project'),appId:v('firebase_app'),senderId:v('firebase_sender'),apiKey:v('firebase_api')},values=Object.values(firebase_config);if(values.some(Boolean)&&!values.every(Boolean))throw Error('Provide all four Firebase public fields, or leave all four empty.');const web={projectId:v('web_project'),appId:v('web_app'),messagingSenderId:v('web_sender'),apiKey:v('web_api')};
 const vapid=v('web_vapid_key'),webValues=[...Object.values(web),vapid];
 if(webValues.some(Boolean)&&!webValues.every(Boolean))throw Error('Provide all five browser notification fields, or leave them empty.');
 if(web.projectId&&firebase_config.projectId&&web.projectId!==firebase_config.projectId)throw Error('Use the same Firebase project for Android and browser notifications.');
 const company_name=v('company_name');
 if(!company_name)throw Error('Enter a company name.');
 await repo.saveSettings({company_name,lunch_start:v('lunch_start'),lunch_end:v('lunch_end'),evening_start:v('evening_start'),evening_end:v('evening_end'),extra_break_minutes:Number(v('extra_break_minutes')),email_high_priority:fd.has('email_high_priority'),firebase_config:{...(values.every(Boolean)?firebase_config:{}),...(webValues.every(Boolean)?{web,web_vapid_key:vapid}:{})}});toast('Break and notification settings saved.');});}});

(async()=>{if(configured()){const r=new Repository();if(r.session){try{await start(false);return;}catch{}}}renderLogin();})();

function reviewRequests(){if(!repo.can('attendance.approve'))return '';const exits=(repo.data.exits||[]).filter(r=>!employeeFilter||r.employee_id===employeeFilter);return `<section class="panel"><header class="panel-head"><h2>Early clock-out requests</h2></header><div class="panel-body">${exits.length?exits.map(r=>`<div class="setting-row"><div><strong>${esc(getEmployee(r.employee_id)?.name||'Employee')} - ${esc(r.status)}</strong><p>${esc(r.reason)} - ${time(r.created_at)}</p><p>${esc(r.decision_note)}</p></div>${r.status==='pending'?`<div class="actions">${btn('Approve','approve-exit','check','',`data-id="${r.id}"`)}${btn('Dismiss','dismiss-exit','close','',`data-id="${r.id}"`)}</div>`:''}</div>`).join(''):'No early clock-out requests.'}</div></section>`; }
function dailyReportsPage(){
 const matches=row=>!employeeFilter||row.employee_id===employeeFilter;
 const files=(repo.data.submissions||[]).filter(matches);
 const reports=(repo.data.dailyReports||[]).filter(matches);
 return heading('Daily Work Reports','Review submitted attendance, breaks, and business calls.')+
  `<div class="actions"><label for="employee-filter">Employee</label>
  <select id="employee-filter" class="activity-select"><option value="">All employees</option>
  ${repo.data.employees.map(e=>`<option value="${esc(e.id)}" ${e.id===employeeFilter?'selected':''}>${esc(e.name)} (${esc(e.employee_code)})</option>`).join('')}</select></div>
  <section class="panel"><header class="panel-head"><h2>Clock-out submissions</h2></header>
  <div class="panel-body">${reports.map(r=>`<details class="setting-row">
  <summary><strong>${esc(getEmployee(r.employee_id)?.name||'Employee')}</strong> &middot; ${esc(r.work_day)} &middot; ${r.calls.length} calls</summary>
  <p>Shift ${time(r.started_at)} to ${time(r.ended_at)} &middot; ${r.breaks.length} breaks</p>
  ${btn('Download Excel','export-daily-report','download','',`data-id="${esc(r.id)}"`)}
  ${r.breaks.map(b=>`<p>${esc(b.kind||'Break')} &middot; ${time(b.start)} to ${time(b.end)}</p>`).join('')}
  <div class="table-wrap"><table><thead><tr><th>Time</th><th>Lead</th><th>Phone</th><th>Direction</th><th>Duration</th><th>Outcome</th><th>Notes</th></tr></thead>
  <tbody>${r.calls.map(c=>`<tr><td>${time(c.started_at)}</td><td>${esc(c.lead_name)}</td><td>${esc(c.phone)}</td>
  <td>${esc(c.direction)}</td><td>${durationLabel(c.duration_seconds)}</td><td>${esc(c.outcome)}</td><td>${esc(c.notes)}</td></tr>`).join('')}</tbody></table></div>
  </details>`).join('')||(repo.local||repo.attendanceAvailable?'No daily reports submitted yet.':'Clock-out submissions require the company backend upgrade.')}</div></section><section class="panel"><header class="panel-head"><h2>Employee report uploads</h2></header><div class="panel-body">${files.length?files.map(f=>`<div class="setting-row"><div><strong>${esc(f.file_name)}</strong><p>${esc(getEmployee(f.employee_id)?.name)} - ${time(f.created_at)} - ${sizes(f.size_bytes)}</p><p>${esc(f.note)}</p></div>${btn('Download','download-submission','download','',`data-id="${f.id}"`)}</div>`).join(''):'No employee report files yet. Uploaded exports are reviewed separately from synced calls.'}</div></section>`;
}
document.addEventListener('click',async event=>{const t=event.target.closest('[data-action]');if(!t||!['approve-exit','dismiss-exit','download-submission'].includes(t.dataset.action))return;try{const permission=t.dataset.action==='download-submission'?'reports.read':'attendance.approve';if(!repo.can(permission))throw Error('Your role does not allow this action.');if(repo.local)throw Error('This action requires a connected workspace.');if(t.dataset.action==='download-submission'){const f=repo.data.submissions.find(f=>f.id===t.dataset.id);const signed=await repo.request('/storage/v1/object/sign/montme-submissions/'+f.file_path,{method:'POST',body:{expiresIn:60}});window.open(getConfig().url+'/storage/v1'+(signed.signedURL||signed.signedUrl),'_blank','noopener');return;}const approve=t.dataset.action==='approve-exit';showModal(approve?'Approve early clock-out':'Dismiss early clock-out','The employee will receive your decision in Notifications.',field('note','Note for employee','','text','maxlength="1000"'),cancel+submit('Send decision'),'exit-decision-form');const form=modal.querySelector('form');form.addEventListener('submit',ev=>{ev.preventDefault();saveForm(form,async()=>{await repo.request('/rest/v1/rpc/decide_early_exit',{method:'POST',body:{request_input:t.dataset.id,approve_input:approve,note_input:new FormData(form).get('note')||''}});toast('Decision sent to employee.');});},{once:true});}catch(e){toast(e.message||String(e),'error');}});

document.addEventListener('click',event=>{
 const exportButton=event.target.closest('[data-action="export-daily-report"]');
 if(exportButton&&repo?.can('reports.read')){
  const report=repo.data.dailyReports.find(r=>r.id===exportButton.dataset.id);
  if(!report)return;
  const rows=[
   ['Employee','Work date (IST)','Clock in','Clock out'],
   [getEmployee(report.employee_id)?.name||'Employee',report.work_day,time(report.started_at),time(report.ended_at)],
   [],['Break','Start','End'],
   ...report.breaks.map(b=>[b.kind||'Break',time(b.start),time(b.end)]),
   [],['Call time','Lead','Phone','Direction','Duration seconds','Outcome','Notes'],
   ...report.calls.map(c=>[time(c.started_at),c.lead_name,c.phone,c.direction,c.duration_seconds,c.outcome,c.notes])
  ];
  download(`daily-work-report-${report.work_day}.xlsx`,workbook(rows),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  return;
 }
 const trigger=event.target.closest('[data-action="set-clock-out"]');
 if(!trigger||!repo?.can('employees.manage'))return;
 const employee=getEmployee(trigger.dataset.id);
 if(!employee)return;
 showModal('Set clock-out time','This time repeats daily in India Standard Time. Leave blank to use the two-hour default.',
  field('clock_out_time','Clock-out time',employee.clock_out_time?.slice(0,5)||'','time'),
  cancel+submit('Save schedule'),'employee-clock-out-form');
 const form=modal.querySelector('form');
 form.addEventListener('submit',event=>{
  event.preventDefault();
  saveForm(form,async()=>{
   const clockOutTime=new FormData(form).get('clock_out_time')||null;
   if(repo.local)await repo.save('employees',{id:employee.id,clock_out_time:clockOutTime});
   else await repo.request('/rest/v1/rpc/set_employee_clock_out',{method:'POST',
    body:{employee_input:employee.id,time_input:clockOutTime}});
   toast('Clock-out schedule saved.');
  });
 });
});
